package com.garagedesk.controller; import com.garagedesk.entity.Bill; import com.garagedesk.service.JobCardService; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/bills") public class BillController{final JobCardService s;public BillController(JobCardService s){this.s=s;}@PostMapping("/job/{id}")@ResponseStatus(HttpStatus.CREATED)public Bill create(@PathVariable Long id,@RequestBody Map<String,Double>b){return s.bill(id,b.getOrDefault("partsAmount",0.0),b.getOrDefault("labourCharge",0.0));}}
